    def run_graph_tool(job):
        """Send one job to the worker, wait, read the answer. Same job twice
        costs nothing the second time."""
        key = json.dumps(job, sort_keys=True)
        if key in GT_CACHE:
            return GT_CACHE[key]
        here = pathlib.Path(tempfile.mkdtemp(dir=GT_DIR))
        job_file, answer_file = here / "job.json", here / "answer.json"
