    # ---- Part 1: reading, drawing and marking the hand-solved networks --------

    def adjacency(edges, n):
        M = np.zeros((n, n), dtype=int)
        for i, j in edges:
            M[i, j] = M[j, i] = 1
        return M

    def parse_nodes(text, n):
        """'2 5, 7' -> the nodes (counted from 0) and what was wrong with it."""
        nodes, problems = [], []
        for word in re.split(r"[,\s]+", text.strip()):
            if not word:
                continue
            if not word.isdigit():
                problems.append(f"“{word}” is not a node number.")
            elif not 1 <= int(word) <= n:
                problems.append(f"There is no node {word}. The nodes are 1 to {n}.")
            else:
                nodes.append(int(word) - 1)
        return nodes, problems

    def read_groups(texts, n):
        groups, problems, owner = [], [], {}
        for g, text in enumerate(texts):
            nodes, bad = parse_nodes(text, n)
            problems += bad
            keep = []
            for v in nodes:
                if v in owner:
                    problems.append(
                        f"Node {v + 1} is in group {owner[v] + 1} and in group "
                        f"{g + 1}. A node goes in one group only."
                    )
                    continue
                owner[v] = g
                keep.append(v)
            if keep:
                groups.append(keep)
        return groups, problems

    def best_agreement(groups, truth):
        """How many nodes sit in the right group, when each of your groups is
        matched to a different true group in whichever way scores best."""
        k = max(truth) + 1
        pool = list(range(k)) + [None] * len(groups)
        best = 0
        for pick in set(itertools.permutations(pool, len(groups))):
            score = sum(
                1
                for g, t in zip(groups, pick)
                if t is not None
                for v in g
                if truth[v] == t
            )
            best = max(best, score)
        return best

    def matrix_svg(M, order, cuts=(), size=320):
        """An adjacency matrix, one square per pair, in the order given. The
        node numbers run along the top and down the left."""
        n = len(order)
        pad = 24
        cell = (size - pad) / n
        out = [
            f'<svg viewBox="0 0 {size} {size}" width="100%" '
            f'style="max-width:{size}px;display:block" '
            'xmlns="http://www.w3.org/2000/svg">',
            f'<rect x="{pad}" y="{pad}" width="{size - pad}" height="{size - pad}" '
            f'fill="{PAPER}" stroke="{INK}" stroke-width="1.6"/>',
        ]
        for a, i in enumerate(order):
            for b, j in enumerate(order):
                if M[i][j]:
                    out.append(
                        f'<rect x="{pad + b * cell:.1f}" y="{pad + a * cell:.1f}" '
                        f'width="{cell:.1f}" height="{cell:.1f}" fill="{INK}"/>'
                    )
        for k in range(1, n):
            p = pad + k * cell
            out.append(
                f'<line x1="{p:.1f}" y1="{pad}" x2="{p:.1f}" y2="{size}" '
                f'stroke="{RULE}" stroke-width="0.6"/>'
                f'<line x1="{pad}" y1="{p:.1f}" x2="{size}" y2="{p:.1f}" '
                f'stroke="{RULE}" stroke-width="0.6"/>'
            )
        for c in cuts:
            p = pad + c * cell
            out.append(
                f'<line x1="{p:.1f}" y1="{pad}" x2="{p:.1f}" y2="{size}" '
                f'stroke="{RUST}" stroke-width="2.4"/>'
                f'<line x1="{pad}" y1="{p:.1f}" x2="{size}" y2="{p:.1f}" '
                f'stroke="{RUST}" stroke-width="2.4"/>'
            )
        for a, i in enumerate(order):
            mid = pad + (a + 0.5) * cell
            out.append(
                f'<text x="{mid:.1f}" y="{pad - 8}" text-anchor="middle" '
                f'font-size="10.5" font-family="{SANS}" font-weight="700" '
                f'fill="{INK}">{i + 1}</text>'
                f'<text x="{pad - 7}" y="{mid + 3.5:.1f}" text-anchor="end" '
                f'font-size="10.5" font-family="{SANS}" font-weight="700" '
                f'fill="{INK}">{i + 1}</text>'
            )
        out.append("</svg>")
        return "".join(out)

    def block_table_html(M, groups):
        """For every pair of your groups: how many of the possible links exist.
        A good grouping makes each cell clearly high or clearly low."""
        head = "".join(
            f'<th style="padding:4px 10px;font-weight:700">group {g + 1}</th>'
            for g in range(len(groups))
        )
        rows = []
        for r, gr in enumerate(groups):
            cells = []
            for s, gs in enumerate(groups):
                if r == s:
                    possible = len(gr) * (len(gr) - 1) / 2
                    links = M[np.ix_(gr, gr)].sum() / 2
                else:
                    possible = len(gr) * len(gs)
                    links = M[np.ix_(gr, gs)].sum()
                share = links / possible if possible else 0.0
                cells.append(
                    f'<td style="padding:6px 10px;text-align:center;'
                    f"background:rgba(57,89,166,{0.55 * share:.2f})\">"
                    f"<b>{share:.2f}</b>"
                    f'<div style="font-size:11px;opacity:0.65">'
                    f"{int(links)} of {int(possible)}</div></td>"
                )
            rows.append(
                f'<tr><th style="padding:4px 10px;text-align:right">group {r + 1}'
                f"</th>{''.join(cells)}</tr>"
            )
        return (
            f'<table style="border-collapse:collapse;font-family:{SANS};'
            f'font-size:14px;color:{INK}"><tr><th></th>{head}</tr>'
            f'{"".join(rows)}</table>'
        )

    def group_inputs(puzzle_index):
        """Four boxes. How many of them a network needs is part of the puzzle."""
        puz = PUZZLES[puzzle_index]
        boxes = []
        for g in range(4):
            members = [str(v + 1) for v, t in enumerate(puz["truth"]) if t == g]
            boxes.append(
                mo.ui.text(
                    value=" ".join(members) if SHOW_ANSWERS else "",
                    placeholder="node numbers, e.g.  2 5 7 11",
                    label=f"group {g + 1}",
                    full_width=True,
                )
            )
        return mo.ui.array(boxes)

    def structure_picker(puzzle_index):
        return mo.ui.radio(
            options=STRUCTURE_OPTIONS,
            value=(
                next(k for k, v in STRUCTURE_OPTIONS.items() if v == PUZZLES[puzzle_index]["kind"])
                if SHOW_ANSWERS
                else None
            ),
            label="✍️ What kind of structure is this?",
        )

    def puzzle_result(puzzle_index, texts, picked):
        """Everything under a network's boxes: your groups, redrawn."""
        puz = PUZZLES[puzzle_index]
        n = len(puz["truth"])
        M = adjacency(puz["edges"], n)
        groups, problems = read_groups(texts, n)
        parts = []
        for p in problems:
            parts.append(note(p, RUST))
        if not groups:
            parts.append(note("Type some node numbers into a box above."))
        else:
            placed = [v for g in groups for v in g]
            loose = [v for v in range(n) if v not in placed]
            order = placed + loose
            cuts = list(itertools.accumulate(len(g) for g in groups))[:-1]
            if loose and groups:
                cuts.append(len(placed))
            score = best_agreement(groups, puz["truth"])
            solved = score == n and len(groups) == max(puz["truth"]) + 1
            left = matrix_svg(M, order, cuts, size=300)
            right = block_table_html(M, groups)
            if loose:
                right += (
                    f'<div style="font-family:{SANS};font-size:13px;opacity:0.65;'
                    f'margin-top:8px">Not in any group yet: '
                    f'{", ".join(str(v + 1) for v in loose)}.</div>'
                )
            parts.append(two_col(left, right, left_basis=300))
            if loose:
                parts.append(
                    note(
                        f"{len(loose)} nodes are in no group yet. Give every node "
                        "a group, then look at the table."
                    )
                )
            elif solved:
                parts.append(
                    note(
                        "<b>Solved.</b> Every node is in the right group. Look at "
                        "the table: each cell is clearly high or clearly low.",
                        BLUE,
                    )
                )
            else:
                parts.append(
                    note(
                        f"{score} of {n} nodes are in the right place. A good "
                        "grouping makes every cell of the table clearly high or "
                        "clearly low. Which cell is in between? The nodes behind "
                        "it are the ones to move.",
                        RUST if score < n - 3 else BLUE,
                    )
                )
        if picked is not None:
            name, what = STRUCTURE[picked]
            truth_name, truth_what = STRUCTURE[puz["kind"]]
            parts.append(
                verdict(
                    picked == puz["kind"],
                    f"<b>Yes: {truth_name}.</b> It has {truth_what}.",
                    f"Not that one. {name} would have {what}. Compare with "
                    "your table: which cells are dark?",
                )
            )
        return mo.vstack(parts)

    # ---- Parts 2 to 4: drawing what graph-tool found ------------------------

    def albers(lon, lat, lon0=-96.0, lat0=37.5, p1=29.5, p2=45.5):
        """The map projection the US usually gets: Albers equal-area conic.
        Done by hand so that no map library has to be installed."""
        lon, lat = np.radians(np.asarray(lon, float)), np.radians(np.asarray(lat, float))
        n = (math.sin(math.radians(p1)) + math.sin(math.radians(p2))) / 2
        c = math.cos(math.radians(p1)) ** 2 + 2 * n * math.sin(math.radians(p1))
        rho = np.sqrt(c - 2 * n * np.sin(lat)) / n
        rho0 = math.sqrt(c - 2 * n * math.sin(math.radians(lat0))) / n
        theta = n * (lon - math.radians(lon0))
        return rho * np.sin(theta), rho0 - rho * np.cos(theta)

    AIR_X, AIR_Y = albers([a[3] for a in AIR], [a[2] for a in AIR])
    BIP_X, BIP_Y = albers([a[3] for a in BIP_AIRPORTS], [a[2] for a in BIP_AIRPORTS])
    AIR_ALASKA = np.array([(a[2] > 50 and a[3] < -129) for a in AIR])

    def draw_outline(ax):
        for ring in DATA["states"]:
            x, y = albers([p[0] for p in ring], [p[1] for p in ring])
            ax.plot(x, y, color=GREY, lw=0.5, zorder=0)

    def edge_matrix(n, edges):
        M = np.zeros((n, n), dtype=np.int8)
        for i, j in edges:
            M[i, j] = M[j, i] = 1
        return M

    def rank_blocks(blocks, weight):
        """Relabel the blocks 0, 1, 2, ... with the one whose members have the
        highest `weight` first. Busiest block first."""
        blocks = np.asarray(blocks)
        ids = sorted(set(blocks.tolist()), key=lambda r: -weight[blocks == r].mean())
        rank = {r: k for k, r in enumerate(ids)}
        return np.array([rank[b] for b in blocks.tolist()])

    def block_density(M, rows_b, cols_b, same):
        """Links found between every pair of blocks, as a share of the links
        that could be there."""
        R, C = rows_b.max() + 1, cols_b.max() + 1
        D = np.zeros((R, C))
        nr, nc = np.bincount(rows_b, minlength=R), np.bincount(cols_b, minlength=C)
        for r in range(R):
            for s in range(C):
                links = M[np.ix_(rows_b == r, cols_b == s)].sum()
                if same and r == s:
                    possible = nr[r] * (nr[r] - 1)  # each pair is counted twice
                else:
                    possible = nr[r] * nc[s]
                D[r, s] = links / possible if possible else 0.0
        return D

    def style_matrix_axes(ax, title=None):
        ax.set_xticks([])
        ax.set_yticks([])
        for side in ax.spines.values():
            side.set_color(GREY)
        if title:
            ax.set_title(title, fontsize=9, color=INK, loc="left")

    def draw_dots(ax, M, rows, cols, s, cuts_r=(), cuts_c=(), title=None):
        sub = M[np.ix_(rows, cols)]
        r, c = np.nonzero(sub)
        ax.scatter(c, r, s=s, marker="s", linewidths=0, color=INK, rasterized=True)
        for k in cuts_c:
            ax.axvline(k - 0.5, color=RUST, lw=0.7, alpha=0.7)
        for k in cuts_r:
            ax.axhline(k - 0.5, color=RUST, lw=0.7, alpha=0.7)
        ax.set_xlim(-0.5, len(cols) - 0.5)
        ax.set_ylim(len(rows) - 0.5, -0.5)
        ax.set_aspect("equal")
        style_matrix_axes(ax, title)

    def draw_summary(ax, D, row_names, col_names, title=None):
        ramp = LinearSegmentedColormap.from_list("paper_blue", [PAPER, BLUE])
        ax.imshow(np.sqrt(D), cmap=ramp, vmin=0, vmax=1, aspect="auto")
        ax.set_yticks(range(len(row_names)))
        ax.set_yticklabels(row_names, fontsize=6.5, color=INK)
        ax.set_xticks(range(len(col_names)))
        ax.set_xticklabels(col_names, fontsize=6.5, color=INK, rotation=90)
        ax.tick_params(length=0)
        for side in ax.spines.values():
            side.set_color(GREY)
        if title:
            ax.set_title(title, fontsize=9, color=INK, loc="left")

    def cuts_of(b):
        return list(np.cumsum(np.bincount(b))[:-1])

    def block_names_by(b, weight, label):
        """'1 ATL (4)': rank, the member with the highest weight, and the size."""
        out = []
        for k in range(b.max() + 1):
            mem = np.flatnonzero(b == k)
            top = mem[np.argmax(weight[mem])]
            out.append(f"{k + 1} {label[top]} ({len(mem)})")
        return out

    def figure(rows, cols, height, ratios=None):
        fig, axs = plt.subplots(
            rows, cols, figsize=(8, height), facecolor=PAPER,
            gridspec_kw=dict(width_ratios=ratios) if ratios else None,
        )  # fmt: skip
        for ax in np.atleast_1d(axs).ravel():
            ax.set_facecolor(PAPER)
        return fig, axs

    def finish(fig):
        fig.tight_layout()
        plt.close(fig)
        return fig

    def edge_list_ready(edges, g):
        """True once `edges` holds the same links as the igraph graph."""
        try:
            got = {tuple(sorted(map(int, e))) for e in edges}
            want = {tuple(sorted(e)) for e in g.get_edgelist()}
        except Exception:
            return False
        return got == want and len(list(edges)) == g.ecount()

    def png_html(data, width="100%"):
        b64 = base64.b64encode(data).decode("ascii")
        return mo.Html(
            f'<img src="data:image/png;base64,{b64}" style="width:{width};'
            'max-width:720px;display:block;margin:0 auto"/>'
        )

    def entropy_of(marginal):
        return -sum(p * math.log(p) for p in marginal.values() if p > 0)

    def pct(p):
        return f"{round(100 * p)}%"


