@app.cell(hide_code=True)
def _(foot_fit):
    if foot_fit is None:
        _out = WAITING
    else:
        _M = edge_matrix(FOOT_N, FOOT_EDGES)
        _deg = _M.sum(axis=1)
        _b = rank_blocks(foot_fit["blocks"], _deg)
        _order = np.lexsort((-_deg, _b))
        # A block gets the name of the conference most of its teams play in.
        _names, _used = [], {}
        for _k in range(_b.max() + 1):
            _c = int(np.bincount(FOOT_CONF[_b == _k], minlength=12).argmax())
            _used[_c] = _used.get(_c, 0) + 1
            _tag = CONFERENCES[_c] + ("" if _used[_c] == 1 else f" ({_used[_c]})")
            _names.append(f"{_k + 1} {_tag}")
        _D = block_density(_M, _b, _b, same=True)
        _fig, _axs = figure(1, 3, 3.4, ratios=[1, 1, 1.15])
        draw_dots(_axs[0], _M, list(range(FOOT_N)), list(range(FOOT_N)), 3.2,
                  title="A→Z order")  # fmt: skip
        draw_dots(_axs[1], _M, _order, _order, 3.2, cuts_of(_b), cuts_of(_b),
                  title="graph-tool's blocks")  # fmt: skip
        draw_summary(_axs[2], _D, _names, list(range(1, len(_names) + 1)),
                     title="links per block pair")  # fmt: skip
        _out = finish(_fig)
    _out
    return


@app.cell(hide_code=True)
def _(foot_fit):
    if foot_fit is None:
        _out = WAITING
    else:
        _b = rank_blocks(foot_fit["blocks"], edge_matrix(FOOT_N, FOOT_EDGES).sum(axis=1))
        _rows, _agree, _off = [], 0, {}
        for _k in range(_b.max() + 1):
            _mem = np.flatnonzero(_b == _k)
            _count = np.bincount(FOOT_CONF[_mem], minlength=12)
            _agree += int(_count.max())
            for _c in np.flatnonzero(_count):
                if _c != _count.argmax():
                    _off[_c] = _off.get(_c, 0) + int(_count[_c])
            _mix = ", ".join(
                f"{CONFERENCES[c]} {int(_count[c])}" for c in np.argsort(-_count) if _count[c]
            )
            _rows.append(
                f'<tr><td style="padding:3px 12px 3px 0;text-align:right"><b>{_k + 1}</b></td>'
                f'<td style="padding:3px 12px 3px 0">{len(_mem)} teams</td>'
                f'<td style="padding:3px 0">{_mix}</td></tr>'
            )
        _who = ", ".join(
            f"{CONFERENCES[c]} {n}" for c, n in sorted(_off.items(), key=lambda kv: -kv[1])
        )
        _out = mo.vstack(
            [
                mo.md(
                    "graph-tool never saw the conferences. Here is who is in each "
                    "block, by the conference they really play in:"
                ),
                mo.Html(
                    f'<table style="border-collapse:collapse;font-family:{SANS};'
                    f'font-size:14px;color:{INK}">{"".join(_rows)}</table>'
                ),
                note(
                    f"<b>{_agree} of {FOOT_N} teams</b> ({pct(_agree / FOOT_N)}) sit "
                    "in a block whose main conference is their own. The other "
                    f"{FOOT_N - _agree} are in a block with another conference's "
                    f"teams: {_who}. An <i>Independent</i> belongs to no conference, "
                    "so there is no block that is its own."
                ),
            ]
        )
    _out
    return


