@app.cell(hide_code=True)
def _(bip_fit):
    if bip_fit is None:
        _out = WAITING
    else:
        _na, _np = len(BIP_AIRLINES), len(BIP_AIRPORTS)
        _n = _na + _np
        _M = edge_matrix(_n, [[a, _na + p] for a, p in BIP_EDGES])
        _deg = _M.sum(axis=1)
        _label = [x.split(" (")[0][:18] for x in BIP_AIRLINES] + [a[0] for a in BIP_AIRPORTS]
        _is_airline = np.arange(_n) < _na
        # One alphabetical list for both kinds, so that the matrix does not
        # give the two kinds away before graph-tool has looked.
        _az = sorted(range(_n), key=lambda i: _label[i])
        _b = rank_blocks(bip_fit["blocks"], _deg)
        _order = np.lexsort((-_deg, _b))
        _names = block_names_by(_b, _deg, _label)
        _D = block_density(_M, _b, _b, same=True)
        _fig, _axs = figure(1, 3, 3.3, ratios=[1, 1, 1.25])
        draw_dots(_axs[0], _M, _az, _az, 1.3, title="A→Z order")
        draw_dots(_axs[1], _M, _order, _order, 1.3, cuts_of(_b), cuts_of(_b),
                  title="graph-tool's blocks")  # fmt: skip
        draw_summary(_axs[2], _D, _names, list(range(1, len(_names) + 1)),
                     title="links per block pair")  # fmt: skip
        _lists, _mixed = [], 0
        for _k in range(_b.max() + 1):
            _mem = np.flatnonzero(_b == _k)
            _mem = _mem[np.argsort(-_deg[_mem])]
            _k_air = int(_is_airline[_mem].sum())
            if 0 < _k_air < len(_mem):
                _mixed += 1
                _what = f"{_k_air} airlines and {len(_mem) - _k_air} airports"
            else:
                _what = f"{len(_mem)} {'airlines' if _k_air else 'airports'}"
            _lists.append(
                f"<li><b>{_k + 1}</b> · {_what}: "
                f"{', '.join(_label[i] for i in _mem[:7])}{' …' if len(_mem) > 7 else ''}</li>"
            )
        _msgs = [finish(_fig)]
        if _mixed:
            _msgs.append(
                note(
                    f"{_mixed} block(s) hold airlines and airports together. "
                    "Nobody told graph-tool that the two are different kinds, "
                    "and it kept some small airlines with the airports they serve. "
                    "Tick the box above to forbid that.",
                    RUST,
                )
            )
        _msgs.append(
            mo.Html(
                f'<div style="font-family:{SANS};font-size:14px;color:{INK}">'
                "<b>Who is in each block</b>, busiest first:"
                f'<ul style="margin:6px 0">{"".join(_lists)}</ul></div>'
            )
        )
        _out = mo.vstack(_msgs)
    _out
    return


