@app.cell(hide_code=True)
def _(samp_fit):
    if samp_fit is None:
        _out = WAITING
    else:
        _top = np.array([max(m.values()) for m in samp_fit["marginal"]])
        _mode = np.array(samp_fit["mode"])
        # A block is named by the conference most of its teams play in.
        _name = {}
        for _k in sorted(set(_mode.tolist())):
            _c = int(np.bincount(FOOT_CONF[_mode == _k], minlength=12).argmax())
            _name[_k] = CONFERENCES[_c]
        _g = igraph.Graph(n=FOOT_N, edges=FOOT_EDGES)
        random.seed(3)
        _xy = np.array(_g.layout_fruchterman_reingold())
        _span = np.ptp(_xy, axis=0).max()
        _unsure = [i for i in np.argsort(_top) if _top[i] < 0.95]
        _blocks_used = []
        for _i in _unsure:
            for _k, _p in sorted(samp_fit["marginal"][_i].items(), key=lambda kv: -kv[1]):
                if _k not in _blocks_used:
                    _blocks_used.append(_k)
        _fig, _ax = figure(1, 1, 5.0)
        _segs = [[tuple(_xy[i]), tuple(_xy[j])] for i, j in FOOT_EDGES]
        _ax.add_collection(LineCollection(_segs, colors=INK, linewidths=0.4, alpha=0.14))
        _sure = [i for i in range(FOOT_N) if i not in _unsure]
        _ax.scatter(_xy[_sure, 0], _xy[_sure, 1], s=14, color=GREY, lw=0, zorder=2)
        _r = 0.028 * _span
        for _i in _unsure:
            _angle = 0.0
            for _k, _p in sorted(samp_fit["marginal"][_i].items(), key=lambda kv: -kv[1]):
                _col = PIE_COLORS[_blocks_used.index(_k) % len(PIE_COLORS)]
                _ax.add_patch(
                    Wedge(_xy[_i], _r, _angle, _angle + 360 * _p, fc=_col, ec=PAPER, lw=0.6, zorder=4)
                )
                _angle += 360 * _p
            _ax.annotate(
                FOOT_NAMES[_i], _xy[_i], xytext=(0, 1.9 * _r * 72 / 6), fontsize=8,
                color=INK, ha="center", textcoords="offset points", zorder=5,
            )  # fmt: skip
        _ax.set_aspect("equal")
        _ax.axis("off")
        _chips = "".join(
            f'<span style="display:inline-block;margin-right:16px">'
            f'<span style="display:inline-block;width:11px;height:11px;'
            f"border-radius:3px;background:{PIE_COLORS[n % len(PIE_COLORS)]};"
            f'margin-right:6px"></span>{_name.get(k, "another block")}</span>'
            for n, k in enumerate(_blocks_used)
        )
        _lines = []
        for _i in _unsure:
            _parts = " · ".join(
                f"{_name.get(_k, 'another block')} {pct(_p)}"
                for _k, _p in sorted(samp_fit["marginal"][_i].items(), key=lambda kv: -kv[1])[:3]
            )
            _lines.append(
                f"<tr><td style='padding:3px 14px 3px 0'><b>{FOOT_NAMES[_i]}</b></td>"
                f"<td style='padding:3px 14px 3px 0'>plays in: "
                f"{CONFERENCES[FOOT_CONF[_i]]}</td><td style='padding:3px 0'>"
                f"put in: {_parts}</td></tr>"
            )
        _indep = sum(1 for i in _unsure if FOOT_CONF[i] == 5)
        _out = mo.vstack(
            [
                finish(_fig),
                mo.Html(
                    f'<div style="font-family:{SANS};font-size:13px;color:{INK}">'
                    f"A slice is a block, named by the conference most of its teams "
                    f"play in:<br>{_chips}</div>"
                ),
                mo.md(
                    f"Only **{len(_unsure)} of {FOOT_N} teams** were put in more "
                    "than one block, and the table shows where."
                ),
                mo.Html(
                    f'<table style="border-collapse:collapse;font-family:{SANS};'
                    f'font-size:14px;color:{INK}">{"".join(_lines)}</table>'
                ),
                note(
                    (
                        f"{_indep} of them play in the <i>Independents</i>, the "
                        "teams with no conference. A team with no conference has "
                        "its games spread over several blocks, so graph-tool "
                        "hesitates between them. That is the right thing to do. "
                        if _indep
                        else "Their games are spread over several blocks, so "
                        "graph-tool hesitates between them. That is the right "
                        "thing to do. "
                    )
                    + "The football network is clean, so only a few teams are in "
                    "doubt. A messier network has many more."
                ),
            ]
        )
    _out
    return


